import sys
from collections import defaultdict

def dfs(node, parent, depth, depths, children):
    depths[node] = depth
    for neighbor in adj[node]:
        if neighbor != parent:
            children[node].append(neighbor)
            dfs(neighbor, node, depth + 1, depths, children)

def lca(u, v, depths, children, parent):
    while depths[u] > depths[v]:
        u = parent[u]
    while depths[v] > depths[u]:
        v = parent[v]
    while u != v:
        u = parent[u]
        v = parent[v]
    return u

def count_pairs(n, edges):
    global adj, parent, depths, children
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent = [0] * (n + 1)
    depths = [0] * (n + 1)
    children = defaultdict(list)
    dfs(1, 0, 0, depths, children)
    for node in range(1, n + 1):
        for child in children[node]:
            parent[child] = node
    total_pairs = 0
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):
            for c in range(1, n + 1):
                if c == a or c == b:
                    continue
                for d in range(c + 1, n + 1):
                    if d == a or d == b:
                        continue
                    ab_lca = lca(a, b, depths, children, parent)
                    cd_lca = lca(c, d, depths, children, parent)
                    if ab_lca != cd_lca and ab_lca != c and ab_lca != d and cd_lca != a and cd_lca != b:
                        total_pairs += 1
    return total_pairs

n = int(sys.stdin.readline())
edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n - 1)]
print(count_pairs(n, edges))
